def run(arguments):
  unit_price = arguments['unit_price']
  fixed_cost = arguments['fixed_cost']
  variable_cost = arguments['variable_cost']
  c = unit_price - variable_cost
  units = int(fixed_cost / c)
  if units * c < fixed_cost:
    units += 1
  return {
    'break_even_units': units,
    'break_even_revenue': float(units * unit_price),
    'contribution_per_unit': float(c)
  }
